func testTenantToManyAddOpTenantIdAPIKeys(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Tenant
	var b, c, d, e APIKey

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, tenantDBTypes, false, strmangle.SetComplement(tenantPrimaryKeyColumns, tenantColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*APIKey{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, apiKeyDBTypes, false, strmangle.SetComplement(apiKeyPrimaryKeyColumns, apiKeyColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*APIKey{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddTenantIdAPIKeys(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.ID != first.TenantId {
			t.Error("foreign key was wrong value", a.ID, first.TenantId)
		}
		if a.ID != second.TenantId {
			t.Error("foreign key was wrong value", a.ID, second.TenantId)
		}

		if first.R.TenantIdTenant != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.TenantIdTenant != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.TenantIdAPIKeys[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.TenantIdAPIKeys[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.TenantIdAPIKeys().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
